import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { User } from '@/types/api';

import { getUsersQueryOptions } from './get-users';

export const updateUserRoleInputSchema = z.object({
  role: z.enum(['ADMIN', 'USER']),
});

export type UpdateUserRoleInput = z.infer<typeof updateUserRoleInputSchema>;

export const updateUserRole = ({
  userId,
  data,
}: {
  userId: string;
  data: UpdateUserRoleInput;
}): Promise<User> => {
  return api.patch(`/users/${userId}/role`, data);
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const queryClient = useQueryClient();

  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      queryClient.invalidateQueries({
        queryKey: getUsersQueryOptions().queryKey,
      });
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updateUserRole,
  });
};
EOF
cat > features/users/components/update-user-role.tsx <<'EOF'
import { useNotifications } from '@/components/ui/notifications';
import { useUser } from '@/lib/auth';
import { User } from '@/types/api';

import { useUpdateUserRole } from '../api/update-user-role';

type UpdateUserRoleProps = {
  id: string;
  role: User['role'];
};

const roles: User['role'][] = ['ADMIN', 'USER'];

export const UpdateUserRole = ({ id, role }: UpdateUserRoleProps) => {
  const user = useUser();
  const { addNotification } = useNotifications();
  const updateUserRoleMutation = useUpdateUserRole({
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'User Role Updated',
        });
      },
    },
  });

  return (
    <select
      aria-label="Role"
      className="block rounded-md border-gray-300 py-1 pl-2 pr-8 text-sm focus:border-blue-500 focus:outline-none focus:ring-blue-500"
      value={role}
      disabled={user.data?.id === id || updateUserRoleMutation.isPending}
      onChange={(e) =>
        updateUserRoleMutation.mutate({
          userId: id,
          data: { role: e.target.value as User['role'] },
        })
      }
    >
      {roles.map((r) => (
        <option key={r} value={r}>
          {r}
        </option>
      ))}
    </select>
  );
};
EOF
